'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { cn } from '@/lib/utils'

const TABS = [
  { label: 'Revenue', href: '/reports/revenue' },
  { label: 'Artists', href: '/reports/artists' },
  { label: 'Clients', href: '/reports/clients' },
  { label: 'Bookings', href: '/reports/bookings' },
  { label: 'Inventory', href: '/reports/inventory' },
  { label: 'AI Usage', href: '/reports/ai' },
]

/**
 * Path-based tab navigation for the /reports/* routes.
 * Matches PageTabs visual style (underline, active = primary, h-10, text-sm).
 */
export function ReportsTabNav() {
  const pathname = usePathname()

  return (
    <div
      role="tablist"
      aria-label="Report sections"
      className={cn(
        'flex items-end gap-0 border-b border-border/60',
        'overflow-x-auto scrollbar-none',
        '[mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)]',
        'md:[mask-image:none]',
      )}
    >
      {TABS.map((tab) => {
        const isActive = pathname === tab.href || pathname.startsWith(tab.href + '/')
        return (
          <Link
            key={tab.href}
            href={tab.href}
            role="tab"
            aria-selected={isActive}
            className={cn(
              'relative flex items-center px-3 h-10 shrink-0',
              'text-sm whitespace-nowrap transition-colors duration-150',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0',
              isActive
                ? [
                    'font-semibold text-foreground',
                    'after:absolute after:bottom-0 after:inset-x-0 after:h-0.5 after:bg-primary after:rounded-full',
                  ]
                : 'font-medium text-muted-foreground hover:text-foreground',
            )}
          >
            {tab.label}
          </Link>
        )
      })}
    </div>
  )
}

